mapper.select:
SELECT wmrs.id, wm.sys_classify AS sysClassify, wm.module_classify AS moduleClassify, db.name AS moduleStatusName, wmrs.module_status FROM work_menu wm LEFT JOIN work_menu_ref_status wmrs ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value" AND db."type" = 'moduleStatus'
AND wm.sys_classify = #{sysClassify}
ORDER BY wm.sys_classify,wm.id

SELECT max(wmrs.id) id, wm.sys_classify AS sysClassify, wm.module_classify AS moduleClassify, '' AS moduleStatusName FROM work_menu wm LEFT JOIN work_menu_ref_status wmrs ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value"
AND wm.sys_classify = #{sysClassify}
GROUP BY wm.sys_classify, wm.module_classify ORDER BY sys_classify,max(wmrs.id)

SELECT wo.id, wmrs.id AS moduleStatusId, wm.id AS menu_id, wm.sys_classify AS sysClassify, wm.module_classify AS moduleClassify, wm.module_code AS moduleCode, db.name AS moduleStatusName, wmrs.module_status AS moduleStatus, wmrs.module_url AS moduleUrl, wmrs.module_param AS moduleParam FROM work_option wo LEFT JOIN work_menu_ref_status wmrs ON wo.work_menu_id = wmrs.id LEFT JOIN work_menu wm ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value" WHERE wo.is_deleted = FALSE AND wo.type = '1' AND wm.module_code NOT IN ('qcInfo')
AND wo.option_user_id = #{optionUserId}
ORDER BY wm.sys_classify,wm.id

SELECT wo.id, wmrs.id AS moduleStatusId, wm.sys_classify AS sysClassify, wm.id AS menu_id, wm.module_classify AS name, wmrs.module_url AS moduleUrl, wmrs.module_param AS moduleParam FROM work_option wo LEFT JOIN work_menu_ref_status wmrs ON wo.work_menu_id = wmrs.id LEFT JOIN work_menu wm ON wm.id = wmrs.menu_id LEFT JOIN dict_basic db ON wmrs.module_status = db."value" WHERE wo.is_deleted = FALSE AND wo.type = '2'
AND wo.option_user_id = #{optionUserId}
ORDER BY wm.sys_classify,wm.id

SELECT max(ptm.id) AS id, wm.module_classify, pm.business_code, pm.business_name, pm.business_id, pm.business_key, pm.create_user_id, EXTRACT(EPOCH FROM (pm.end_time - pm.start_time)) AS approveDuration, pm.create_time, pm.approve_status, concat(wm.detail_url,pm.business_id) as detail_url FROM process_management pm INNER JOIN process_task_management ptm ON pm.process_instance_id = ptm.process_instance_id AND ptm.is_deleted = FALSE INNER JOIN work_menu wm ON pm.business_key = wm.module_code AND wm.is_deleted = FALSE LEFT JOIN process_task_cc cc ON cc.task_management_id = ptm.id AND cc.is_deleted = FALSE WHERE pm.is_deleted = FALSE
AND ptm.task_status = 'approveIng' AND ptm.cur_approve_id = #{params.userId}
AND (ptm.task_status = 'approve' OR ptm.task_status = 'reject') AND ptm.cur_approve_id = #{params.userId}
AND cc.cc_user_id = #{params.userId}
AND ptm.create_user_id = #{params.userId}
AND wm.sys_classify IN
#{item}
AND pm.business_code ilike concat('%',#{params.sourceCode},'%')
GROUP BY wm.module_classify, pm.business_code, pm.business_name, pm.business_id, pm.business_key, pm.create_user_id, EXTRACT(EPOCH FROM (pm.end_time - pm.start_time)), pm.create_time, pm.approve_status, concat(wm.detail_url,pm.business_id)

SELECT count(*) AS quantity, t.sys_classify FROM ( SELECT max(ptm.id) AS id, wm.module_classify, pm.business_code, pm.business_name, pm.business_id, pm.business_key, pm.create_user_id, EXTRACT(EPOCH FROM (pm.end_time - pm.start_time)) AS approveDuration, pm.create_time, pm.approve_status, wm.sys_classify, concat(wm.detail_url,pm.business_id) as detail_url FROM process_management pm INNER JOIN process_task_management ptm ON pm.process_instance_id = ptm.process_instance_id AND ptm.is_deleted = FALSE INNER JOIN work_menu wm ON pm.business_key = wm.module_code AND wm.is_deleted = FALSE LEFT JOIN process_task_cc cc ON cc.task_management_id = ptm.id AND cc.is_deleted = FALSE WHERE pm.is_deleted = FALSE
AND ptm.task_status = 'approveIng' AND ptm.cur_approve_id = #{params.userId}
AND (ptm.task_status = 'approve' OR ptm.task_status = 'reject') AND ptm.cur_approve_id = #{params.userId}
AND cc.cc_user_id = #{params.userId}
AND ptm.create_user_id = #{params.userId}
AND wm.sys_classify IN
#{item}
AND pm.business_code ilike concat('%',#{params.sourceCode},'%')
GROUP BY wm.module_classify, pm.business_code, pm.business_name, pm.business_id, pm.business_key, pm.create_user_id, wm.sys_classify, EXTRACT(EPOCH FROM (pm.end_time - pm.start_time)), pm.create_time, pm.approve_status, concat(wm.detail_url,pm.business_id) )t GROUP BY t.sys_classify
